/**
 * (a) Claim this (orderId, index). True when this delivery is the first one that got
 * here, false when an earlier delivery already applied the element.
 */
async function claimElement(orderId, index, bookId) {
  const params = {
    TableName: idempotencyTable,
    Item: {
      pk: `${MARKER_PREFIX}#${orderId}#${index}`,
      orderId: orderId,
      bookId: bookId,
      createdAt: Date.now(),
      expiresAt: Math.floor(Date.now() / 1000) + MARKER_TTL_SECONDS
    },
    ConditionExpression: 'attribute_not_exists(pk)'
  };

  try {
    await docClient.send(new PutCommand(params));
    return true;
  } catch (error) {
    if (error.name === 'ConditionalCheckFailedException') return false;
    throw error;
  }
}

/**
 * (b) The counter update, utils/bestsellers.js:17-26 verbatim: ADD on the key, no
 * ConditionExpression, so the first sale creates the row.
 */
async function addSalesCount(bookId, quantity) {
  const params = {
    TableName: bestsellersTable,
    Key: { bookId: bookId },
    UpdateExpression: 'ADD salesCount :qty',
    ExpressionAttributeValues: {
      ':qty': quantity
    }
  };

  await docClient.send(new UpdateCommand(params));
}

async function withTransientRetry(operation, what) {
  let lastError = null;
  for (let attempt = 1; attempt <= TRANSIENT_ATTEMPTS; attempt++) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;
      if (!isTransient(error)) throw error;
      if (attempt < TRANSIENT_ATTEMPTS) {
        console.warn(`Retrying ${what} (attempt ${attempt}):`, error.message);
        await sleep(TRANSIENT_BACKOFF_MS * attempt);
      }
    }
  }
  throw lastError;
}

