            if ev.get("Type")!="Api": errs.append(f"{ln}.{en}: Type {ev.get('Type')} but api_type=rest")
            ep=ev["Properties"]
            if "PayloadFormatVersion" in ep: errs.append(f"{ln}.{en}: REST Api events take no PayloadFormatVersion")
            key=f"{str(ep.get('Method','')).upper()} {norm(str(ep.get('Path','')))}"
            if key not in bp_eps: errs.append(f"{ln}.{en}: event {key} has no blueprint entry_point")
            else:
                seen.add(key)
                fname, auth = bp_eps[key]
                if fname != bf["name"]: errs.append(f"{ln}.{en}: event {key} belongs to blueprint fn {fname}")
                has_none = isinstance(ep.get("Auth"),dict) and str(ep["Auth"].get("Authorizer","")).upper()=="NONE"
                if auth=="none" and not has_none: errs.append(f"{ln}.{en}: auth none but no override")
                if auth=="required" and has_none: errs.append(f"{ln}.{en}: auth required but NONE override")
            rid = ep.get("RestApiId")
            if res.get(str(rid),{}).get("Type")!="AWS::Serverless::Api": errs.append(f"{ln}.{en}: RestApiId {rid} is not a Serverless::Api")
    elif bf["trigger_type"]=="sqs":
        sqs=[ev for ev in events.values() if ev.get("Type")=="SQS"]
        if not sqs: errs.append(f"{ln}: trigger_type sqs but no SQS event")
        for ev in sqs:
            q=str(ev["Properties"].get("Queue"))
            base=q.split(".")[0]
            if base not in res or res[base].get("Type")!="AWS::SQS::Queue": errs.append(f"{ln}: SQS event queue ref {q} unknown")
            frt = ev["Properties"].get("FunctionResponseTypes")
            returns_fail = "batchItemFailures" in (d/"index.js").read_text(encoding="utf-8") if (d:="") or True else False
            print(f"  {ln}: BatchSize={ev['Properties'].get('BatchSize')} FunctionResponseTypes={frt}")
for k,(fn,_) in bp_eps.items():
    if k not in seen: errs.append(f"blueprint entry_point {k} ({fn}) has no Api event")

# 4. policies sanity: every !Ref in policies resolves
for ln,f in fns.items():
    for pol in f.get("Properties",{}).get("Policies") or []:
        for tmpl, spec in (pol.items() if isinstance(pol,dict) and len(pol)==1 and not isinstance(pol.get("Version"),str) else []):
            v = spec if isinstance(spec,dict) else {}
            for key,val in v.items():
                if isinstance(val,str) and val not in res: errs.append(f"{ln}: policy {tmpl}.{key} ref '{val}' unknown")

print("logical names:", sorted(fns))
print("\nERRORS:" if errs else "\nNO ERRORS")
for e in errs: print(" -", e)
