import json, yaml, sys
from pathlib import Path
WS = Path(r"D:\Emma\MyLab\Mono2SLs\Mono2Sls-artifacts\M2S\runs\bookstore-full")
merged = (WS/"output/template.part1.yaml").read_text(encoding="utf-8") + "\n" + (WS/"output/template.part2.yaml").read_text(encoding="utf-8")

# strip CFN short tags for a plain dict (SAM takes plain JSON)
class L(yaml.SafeLoader): pass
def multi(loader, tag, node):
    if isinstance(node, yaml.ScalarNode): return {tag.lstrip("!"): loader.construct_scalar(node)}
    if isinstance(node, yaml.SequenceNode): return {tag.lstrip("!"): loader.construct_sequence(node, deep=True)}
    return {tag.lstrip("!"): loader.construct_mapping(node, deep=True)}
L.add_multi_constructor("!", multi)
def expand(v):
    if isinstance(v, dict):
        if len(v) == 1:
            k = next(iter(v))
            if k in ("Ref", "GetAtt", "Sub", "Condition"):
                val = v[k]
                if k == "Ref": return {"Ref": val}
                if k == "GetAtt": return {"Fn::GetAtt": val if isinstance(val, list) else val.split(".")}
                if k == "Sub": return {"Fn::Sub": val}
        return {k: expand(u) for k, u in v.items()}
    if isinstance(v, list): return [expand(u) for u in v]
    return v
tmpl = expand(yaml.load(merged, Loader=L))
Path("s3b_merged.json").write_text(json.dumps(tmpl, indent=1), encoding="utf-8")

