    print("event source mappings:", json.dumps(esm, indent=1))
    # the consumer role must allow poll + both tables
    consumer_role = res.get("BestsellersUpdateFunction", {}).get("Properties", {}).get("Role")
    if isinstance(consumer_role, dict):
        rid = consumer_role.get("Fn::GetAtt", [None])
